"use client";

import { useEffect, useMemo, useState } from "react";
import { supabase } from "./supabase-client";

type UserProfile = { id:string; email:string|null; full_name:string|null; avatar_url:string|null; platform_role:string };
type OrganizationAccess = { id:string; name:string; slug:string; status:string; memberRole:string };
type ProviderInvitation = { id:string; organization_id:string; email:string; status:string; expires_at:string; created_at:string; organizations:{name:string}|null };

const products = [
  { id: 1, name: "Aguacate Hass premium", store: "Huerta del Valle", price: 8900, old: 10900, rating: "4.9", tag: "-18%", image: "🥑", color: "#dfeec9", unit: "Malla x 4" },
  { id: 2, name: "Salmón fresco porción", store: "Mar & Río", price: 24900, old: 28900, rating: "4.8", tag: "-14%", image: "🐟", color: "#fee0da", unit: "500 g" },
  { id: 3, name: "Pan artesanal de masa madre", store: "Miga Casa", price: 12500, old: null, rating: "4.9", tag: "Nuevo", image: "🥖", color: "#f6e8c8", unit: "650 g" },
  { id: 4, name: "Fresas seleccionadas", store: "Frutos de Casa", price: 9900, old: 12900, rating: "4.7", tag: "-23%", image: "🍓", color: "#ffe0e6", unit: "Bandeja 500 g" },
  { id: 5, name: "Café especial de origen", store: "Cumbre Café", price: 27800, old: null, rating: "5.0", tag: "Top", image: "☕", color: "#ede1d4", unit: "340 g" },
  { id: 6, name: "Queso campesino fresco", store: "La Vaquita", price: 16800, old: 18500, rating: "4.8", tag: "-9%", image: "🧀", color: "#fff3c7", unit: "500 g" },
];

const categories = [
  ["🥬", "Frutas y verduras", "1.240 productos"],
  ["🥩", "Carnes y pescados", "684 productos"],
  ["🥛", "Lácteos y huevos", "920 productos"],
  ["🥐", "Panadería", "356 productos"],
  ["🥤", "Bebidas", "1.102 productos"],
  ["🧴", "Hogar y cuidado", "870 productos"],
];

const money = (value: number) => new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", maximumFractionDigits: 0 }).format(value);

export default function Home() {
  const [cart, setCart] = useState<number[]>([1, 3]);
  const [cartOpen, setCartOpen] = useState(false);
  const [view, setView] = useState<"market" | "dashboard">("market");
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState<(typeof products)[number] | null>(null);
  const [favorite, setFavorite] = useState<number[]>([2]);
  const [checkout, setCheckout] = useState<"closed"|"auth"|"address"|"delivery"|"payment"|"success"|"tracking">("closed");
  const [customer,setCustomer]=useState<{name:string,email:string}|null>(null);
  const [profile,setProfile]=useState<UserProfile|null>(null);
  const [organizations,setOrganizations]=useState<OrganizationAccess[]>([]);
  const [identityLoading,setIdentityLoading]=useState(true);
  const [identityError,setIdentityError]=useState("");
  const [inviteToken,setInviteToken]=useState("");
  const filtered = products.filter((p) => `${p.name} ${p.store}`.toLowerCase().includes(query.toLowerCase()));
  const cartProducts = products.filter((p)=>cart.includes(p.id)).map((p)=>({...p,quantity:cart.filter((id)=>id===p.id).length}));
  const total = useMemo(() => cartProducts.reduce((sum, p) => sum + p.price*p.quantity, 0), [cartProducts]);
  useEffect(()=>{try{const saved=localStorage.getItem("gomarket-demo-cart");if(saved){const parsed=JSON.parse(saved);if(Array.isArray(parsed))setCart(parsed.filter((id)=>products.some(p=>p.id===id)).slice(0,60))}}catch{}},[]);
  useEffect(()=>{try{localStorage.setItem("gomarket-demo-cart",JSON.stringify(cart))}catch{}},[cart]);
  useEffect(()=>{setInviteToken(new URLSearchParams(window.location.search).get("invite")||"")},[]);
  useEffect(()=>{const button=document.querySelector<HTMLButtonElement>(".checkout");if(!button)return;const open=()=>{setCartOpen(false);setCheckout("auth")};button.addEventListener("click",open);return()=>button.removeEventListener("click",open)},[cartOpen]);
  useEffect(()=>{const applySession=async(session:Awaited<ReturnType<typeof supabase.auth.getSession>>["data"]["session"])=>{if(!session){setProfile(null);setOrganizations([]);setIdentityLoading(false);return}const metadata=session.user.user_metadata;setCustomer({name:metadata.full_name||metadata.name||session.user.email?.split("@")[0]||"Cliente",email:session.user.email||""});setIdentityLoading(true);setIdentityError("");const [{data:profileData,error:profileError},{data:members,error:membersError}]=await Promise.all([supabase.from("profiles").select("id,email,full_name,avatar_url,platform_role").eq("id",session.user.id).single(),supabase.from("organization_members").select("organization_id,status,organizations(id,name,slug,status),member_roles(roles(name))").eq("user_id",session.user.id).eq("status","active")]);if(profileError)setIdentityError("No pudimos cargar tu perfil administrativo.");else setProfile(profileData as UserProfile);if(!membersError&&members){setOrganizations(members.map((m:any)=>{const org=Array.isArray(m.organizations)?m.organizations[0]:m.organizations;const assigned=m.member_roles?.flatMap((mr:any)=>Array.isArray(mr.roles)?mr.roles:[mr.roles]).filter(Boolean).map((r:any)=>r.name)||[];return {id:org?.id||m.organization_id,name:org?.name||"Empresa",slug:org?.slug||"",status:org?.status||m.status,memberRole:assigned.join(", ")||"Miembro"}}))}setIdentityLoading(false);if(localStorage.getItem("gomarket-checkout-pending")==="1"){localStorage.removeItem("gomarket-checkout-pending");setCheckout("address")}};supabase.auth.getSession().then(({data})=>applySession(data.session));const {data}=supabase.auth.onAuthStateChange((_event,session)=>{void applySession(session)});return()=>data.subscription.unsubscribe()},[]);

  const add = (id: number) => {
    setCart((items) => items.filter(x=>x===id).length>=12?items:[...items, id]);
    setCartOpen(true);
  };
  const changeQuantity=(id:number,delta:number)=>setCart(items=>delta>0?(items.filter(x=>x===id).length>=12?items:[...items,id]):(()=>{const next=[...items];const index=next.lastIndexOf(id);if(index>=0)next.splice(index,1);return next})());

  if(inviteToken)return <ProviderOnboarding token={inviteToken} customer={customer}/>;
  return (
    <main>
      <div className="announcement"><span>Envíos gratis desde $80.000</span><span className="announcement-center">Compra local. Recibe mejor.</span><span>Ayuda y soporte</span></div>
      <header className="topbar">
        <button className="brand" onClick={() => setView("market")} aria-label="Ir al inicio">
          <span className="brand-mark">go</span><span>market</span>
        </button>
        <button className="location"><span className="pin">●</span><span><small>Entregar en</small><strong>Bogotá, Chapinero</strong></span><b>⌄</b></button>
        <label className="search"><span>⌕</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="¿Qué necesitas hoy?"/><kbd>⌘ K</kbd></label>
        <nav className="actions">
          <button aria-label="Favoritos">♡</button><button aria-label="Notificaciones">♢<i /></button>
          <button className="profile"><span>{customer?customer.name.split(" ").slice(0,2).map(x=>x[0]).join("").toUpperCase():"JS"}</span><span><small>{customer?`Hola, ${customer.name.split(" ")[0]}`:"Hola, Juan"}</small><strong>{customer?customer.email:"Mi cuenta"}</strong></span></button>
          <button className="cart-button" onClick={() => setCartOpen(true)}><span>🛒</span><b>{cart.length}</b><strong>{money(total)}</strong></button>
        </nav>
      </header>
      <div className="navrow">
        <div className="navlinks"><button className={view === "market" ? "active" : ""} onClick={() => setView("market")}>Explorar</button><button>Ofertas</button><button>Nuevos</button><button>Tiendas</button><button onClick={() => setView("dashboard")} className={view === "dashboard" ? "active" : ""}>Panel proveedor</button></div>
        <div className="trust"><span>✓ Pagos seguros</span><span>↺ Compra protegida</span></div>
      </div>

      {view === "market" ? (
        <>
          <section className="hero shell">
            <div className="hero-copy"><span className="eyebrow">MERCADO FRESCO · ENTREGA HOY</span><h1>Todo lo bueno,<br/><em>más cerca de ti.</em></h1><p>Compra en tus tiendas favoritas, combina productos en un solo carrito y nosotros coordinamos el resto.</p><div className="hero-actions"><button className="primary">Comprar ahora <span>→</span></button><button className="play"><i>▶</i> Conoce GoMarket</button></div><div className="hero-proof"><span className="avatars"><i>MR</i><i>AS</i><i>LV</i><i>+2k</i></span><span><b>4.9 de 5</b><small>Más de 2.000 compradores felices</small></span></div></div>
            <div className="hero-art" aria-hidden="true"><div className="blob"></div><span className="leaf leaf-one">◆</span><span className="leaf leaf-two">◆</span><div className="bag"><div className="bag-handle"></div><div className="bag-items"><span>🥬</span><span>🥖</span><span>🍅</span></div><b>go</b><small>market</small></div><div className="floating-card card-delivery"><i>⚡</i><span><b>Entrega express</b><small>En menos de 45 min</small></span></div><div className="floating-card card-local"><i>♥</i><span><b>Compra local</b><small>Apoya a tu comunidad</small></span></div></div>
            <div className="dots"><b></b><i></i><i></i></div>
          </section>

          <section className="shell category-section"><div className="section-heading"><div><span className="kicker">ENCUENTRA LO QUE AMAS</span><h2>Compra por categoría</h2></div><button>Ver todas <span>→</span></button></div><div className="category-grid">{categories.map(([icon,name,count]) => <button className="category-card" key={name}><span>{icon}</span><strong>{name}</strong><small>{count}</small><i>→</i></button>)}</div></section>

          <section className="shell products-section"><div className="section-heading"><div><span className="kicker orange">SELECCIÓN PARA TI</span><h2>{query ? `Resultados para “${query}”` : "Favoritos de la semana"}</h2><p>Productos que todos están amando, seleccionados para ti.</p></div><button>Ver todos <span>→</span></button></div><div className="product-grid">{filtered.map((p) => <article className="product-card" key={p.id}><button className={`heart ${favorite.includes(p.id) ? "liked" : ""}`} onClick={() => setFavorite((f) => f.includes(p.id) ? f.filter((id) => id !== p.id) : [...f,p.id])}>♥</button><button className="product-visual" style={{background:p.color}} onClick={() => setSelected(p)}><span>{p.image}</span><b className={p.tag === "Nuevo" || p.tag === "Top" ? "green" : ""}>{p.tag}</b></button><div className="product-info"><div className="rating">★ {p.rating} <span>· {p.unit}</span></div><button className="product-name" onClick={() => setSelected(p)}>{p.name}</button><small>por <b>{p.store}</b> <i>✓</i></small><div className="price"><span><b>{money(p.price)}</b>{p.old && <del>{money(p.old)}</del>}</span><button onClick={() => add(p.id)} aria-label={`Agregar ${p.name}`}>＋</button></div></div></article>)}</div>{filtered.length === 0 && <div className="empty">No encontramos productos con esa búsqueda.</div>}</section>

          <section className="shell value-strip"><div><i>⚡</i><span><b>Entrega rápida</b><small>Recibe el mismo día</small></span></div><div><i>♧</i><span><b>Productos frescos</b><small>Calidad seleccionada</small></span></div><div><i>♡</i><span><b>Apoya lo local</b><small>Compra a comercios cercanos</small></span></div><div><i>✓</i><span><b>Compra segura</b><small>Pagos siempre protegidos</small></span></div></section>
        </>
      ) : <Dashboard customer={customer} profile={profile} organizations={organizations} loading={identityLoading} error={identityError} onOrganizationsChange={setOrganizations}/>}

      <nav className="mobile-nav"><button onClick={() => setView("market")} className={view === "market" ? "active" : ""}>⌂<small>Inicio</small></button><button>⌕<small>Buscar</small></button><button>▦<small>Categorías</small></button><button onClick={() => setCartOpen(true)}>🛒<small>Carrito</small><b>{cart.length}</b></button><button onClick={() => setView("dashboard")}>○<small>Perfil</small></button></nav>

      {cartOpen && <><button className="overlay" onClick={() => setCartOpen(false)} aria-label="Cerrar carrito"/><aside className="cart-drawer"><div className="drawer-head"><div><span>Tu carrito</span><small>{cart.length} {cart.length===1?"producto":"productos"} · {new Set(cartProducts.map(p => p.store)).size} tiendas</small></div><button onClick={() => setCartOpen(false)}>×</button></div><div className="delivery-progress"><div><span>{total>=80000?"¡Tu envío es gratis!":<>Te faltan <b>{money(80000-total)}</b> para envío gratis</>}</span><strong>{Math.min(100, total/800)}%</strong></div><i><b style={{width:`${Math.min(100,total/800)}%`}}/></i></div><div className="cart-items">{cartProducts.map((p) => <div className="cart-group" key={p.id}><span className="store-label">◉ {p.store} <i>Ver tienda</i></span><div className="cart-item"><span style={{background:p.color}}>{p.image}</span><div><b>{p.name}</b><small>{p.unit} · {money(p.price)} c/u</small><strong>{money(p.price*p.quantity)}</strong></div><div className="quantity"><button onClick={()=>changeQuantity(p.id,-1)} aria-label={`Disminuir ${p.name}`}>−</button><b>{p.quantity}</b><button onClick={()=>changeQuantity(p.id,1)} disabled={p.quantity>=12} aria-label={`Aumentar ${p.name}`}>＋</button></div></div>{p.quantity>=12&&<small className="stock-limit">Máximo disponible para esta prueba: 12 unidades</small>}</div>)}</div>{cartProducts.length === 0 && <div className="empty-cart"><span>🛒</span><h3>Tu carrito está esperando</h3><p>Agrega productos frescos y deliciosos.</p></div>}<div className="cart-summary"><div><span>Subtotal ({cart.length} unidades)</span><b>{money(total)}</b></div><div><span>Domicilio estimado</span><b>{total >= 80000 ? "Gratis" : money(6900)}</b></div><hr/><div className="total"><span>Total</span><b>{money(total + (total && total < 80000 ? 6900 : 0))}</b></div><button className="checkout" disabled={!total}>Continuar al pago <span>→</span></button><small>🔒 Pago seguro y compra protegida</small></div></aside></>}

      {selected && <><button className="overlay" onClick={() => setSelected(null)} aria-label="Cerrar detalle"/><div className="product-modal"><button className="modal-close" onClick={() => setSelected(null)}>×</button><div className="modal-image" style={{background:selected.color}}><span>{selected.image}</span><small>Vista previa del producto</small></div><div className="modal-copy"><span className="kicker">{selected.store}</span><h2>{selected.name}</h2><div className="rating">★ {selected.rating} · 128 opiniones</div><p>Seleccionado por su frescura y calidad. Preparado cuidadosamente por un comercio local de confianza.</p><div className="modal-meta"><span><small>Presentación</small><b>{selected.unit}</b></span><span><small>Disponibilidad</small><b className="stock">En stock</b></span></div><div className="modal-buy"><span><small>Precio</small><b>{money(selected.price)}</b></span><button className="primary" onClick={() => {add(selected.id);setSelected(null)}}>Agregar al carrito</button></div></div></div></>}
      {checkout!=="closed"&&<CheckoutFlow step={checkout} setStep={setCheckout} items={cartProducts} subtotal={total}/>} 
    </main>
  );
}

type CheckoutStep="closed"|"auth"|"address"|"delivery"|"payment"|"success"|"tracking";
function CheckoutFlow({step,setStep,items,subtotal}:{step:Exclude<CheckoutStep,"closed">,setStep:(s:CheckoutStep)=>void,items:Array<(typeof products)[number]&{quantity:number}>,subtotal:number}){
  const [mail,setMail]=useState(""); const [code,setCode]=useState(false); const [otp,setOtp]=useState(""); const [address,setAddress]=useState("Casa"); const [delivery,setDelivery]=useState("express"); const [pay,setPay]=useState("card");
  const fee=subtotal>=80000?0:delivery==="express"?6900:3900; const final=subtotal+fee; const units=items.reduce((sum,p)=>sum+p.quantity,0);
  if(step==="auth")return <><button className="flow-overlay" onClick={()=>setStep("closed")}/><section className="auth-flow"><button className="flow-close" onClick={()=>setStep("closed")}>×</button><div className="flow-logo"><span>go</span><b>market</b></div>{!code?<><small>🔒 TU CARRITO ESTÁ A SALVO</small><h2>Continúa con tu compra</h2><p>Identifícate para elegir la dirección, pagar y hacer seguimiento a tu pedido.</p><button className="google" onClick={async()=>{localStorage.setItem("gomarket-checkout-pending","1");const {error}=await supabase.auth.signInWithOAuth({provider:"google"});if(error){localStorage.removeItem("gomarket-checkout-pending");alert("No pudimos iniciar con Google. Revisa la configuración e inténtalo nuevamente.")}}}><i>G</i> Continuar con Google</button><div className="separator"><i/>o continúa con tu correo<i/></div><label>Correo electrónico<input value={mail} onChange={e=>setMail(e.target.value)} placeholder="tu@email.com" type="email"/></label><button className="flow-primary" disabled={!mail.includes("@")} onClick={()=>setCode(true)}>Recibir código seguro →</button><em>Al continuar aceptas los Términos y la Política de privacidad.</em></>:<><button className="flow-back" onClick={()=>setCode(false)}>← Volver</button><div className="mail-icon">✉</div><h2>Revisa tu correo</h2><p>Enviamos un código de 6 dígitos a <b>{mail}</b>. En esta prueba puedes escribir cualquier código.</p><label>Código de seguridad<input className="otp" value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,""))} maxLength={6} placeholder="000000"/></label><button className="flow-primary" disabled={otp.length<6} onClick={()=>setStep("address")}>Verificar y continuar →</button></>}</section></>;
  if(step==="success")return <><div className="flow-overlay success-overlay"/><section className="success-flow"><div className="big-check">✓</div><small>PEDIDO CONFIRMADO</small><h2>¡Gracias por tu compra, Juan!</h2><p>Los proveedores ya recibieron su parte del pedido. Te avisaremos en cada cambio de estado.</p><div className="order-code"><span>Número de pedido</span><b>#GM-2842</b><button>Copiar</button></div><div className="route"><span className="done"><i>✓</i><b>Confirmado</b></span><em/><span><i>2</i><b>Preparando</b></span><em/><span><i>3</i><b>En camino</b></span><em/><span><i>4</i><b>Entregado</b></span></div><div className="arrival"><i>⚡</i><span><small>Entrega estimada</small><b>Hoy, entre 2:15 y 2:45 p. m.</b></span></div><button className="flow-primary" onClick={()=>setStep("tracking")}>Seguir mi pedido →</button><button className="flow-ghost" onClick={()=>setStep("closed")}>Volver al inicio</button></section></>;
  if(step==="tracking")return <><button className="flow-overlay" onClick={()=>setStep("closed")}/><section className="tracking-flow"><div className="mock-map"><div className="road r1"/><div className="road r2"/><i className="store-pin">HV</i><i className="home-pin">⌂</i><span className="bike">🛵</span><div className="driver"><i>AR</i><span><b>Andrés recoge tu pedido</b><small>Honda Wave · ABC 12D</small></span><button>☎</button></div></div><div className="tracking-info"><button className="flow-close" onClick={()=>setStep("closed")}>×</button><small>PEDIDO #GM-2842</small><h2>Estamos preparando tu compra</h2><p>Huerta del Valle está seleccionando tus productos frescos.</p><div className="timeline"><div className="done"><i>✓</i><span><b>Pedido confirmado</b><small>1:34 p. m.</small></span></div><div className="current"><i>●</i><span><b>Preparando productos</b><small>En proceso · 12 min aprox.</small></span></div><div><i/><span><b>Listo para recoger</b><small>Próximamente</small></span></div><div><i/><span><b>En camino</b><small>Próximamente</small></span></div></div><div className="support">¿Necesitas ayuda? <button>Hablar con soporte</button></div></div></section></>;
  const progress=step==="address"?1:step==="delivery"?2:3;
  return <><button className="flow-overlay" onClick={()=>setStep("closed")}/><section className="checkout-flow"><header><div className="flow-logo"><span>go</span><b>market</b></div><nav>{["Dirección","Entrega","Pago"].map((x,i)=><span className={progress>=i+1?"active":""} key={x}><i>{progress>i+1?"✓":i+1}</i><b>{x}</b>{i<2&&<em/>}</span>)}</nav><button onClick={()=>setStep("closed")}>🔒 Compra segura　×</button></header><main><div className="flow-form">{step==="address"&&<><small>PASO 1 DE 3</small><h1>¿Dónde entregamos tu pedido?</h1><p>Selecciona una dirección guardada o agrega una nueva.</p><div className="choices addresses">{[["Casa","⌂","Carrera 13 # 82-41, Apto 502","Chapinero, Bogotá"],["Oficina","▤","Calle 93 # 11A-28, Piso 7","Chicó, Bogotá"]].map(a=><button className={address===a[0]?"selected":""} onClick={()=>setAddress(a[0])} key={a[0]}><i>{a[1]}</i><span><b>{a[0]}</b><small>{a[2]}<br/>{a[3]}</small></span><strong>✓</strong></button>)}</div><button className="add-new">＋ Agregar nueva dirección</button><label>Indicaciones para la entrega<textarea placeholder="Ej.: dejar en portería, timbre 502..."/></label><button className="flow-primary next" onClick={()=>setStep("delivery")}>Continuar con la entrega →</button></>}{step==="delivery"&&<><button className="flow-back" onClick={()=>setStep("address")}>← Volver a dirección</button><small>PASO 2 DE 3</small><h1>Elige cuándo recibirlo</h1><p>Coordinaremos a todos los proveedores en una sola experiencia.</p><div className="choices vertical">{[["express","⚡","Entrega express","Hoy, entre 2:15 y 2:45 p. m.",subtotal>=80000?"Gratis":"$6.900"],["scheduled","◷","Programar entrega","Hoy, entre 5:00 y 6:00 p. m.",subtotal>=80000?"Gratis":"$3.900"]].map(x=><button className={delivery===x[0]?"selected":""} onClick={()=>setDelivery(x[0])} key={x[0]}><i>{x[1]}</i><span><b>{x[2]}</b><small>{x[3]}</small></span><strong>{x[4]}</strong></button>)}</div><div className="coordination">♧ <span><b>Nosotros coordinamos todo</b><small>Aunque compras en varias tiendas, recibirás actualizaciones unificadas.</small></span></div><button className="flow-primary next" onClick={()=>setStep("payment")}>Continuar al pago →</button></>}{step==="payment"&&<><button className="flow-back" onClick={()=>setStep("delivery")}>← Volver a entrega</button><small>PASO 3 DE 3</small><h1>¿Cómo quieres pagar?</h1><p>Tus datos estarán protegidos. Nunca guardamos la información completa de tu tarjeta.</p><div className="choices vertical payment">{[["card","▣","Tarjeta terminada en 4242","Visa · Juan Sebastián"],["pse","P","PSE","Débito desde tu cuenta bancaria"],["cash","$","Pago contra entrega","Efectivo al recibir"]].map(x=><button className={pay===x[0]?"selected":""} onClick={()=>setPay(x[0])} key={x[0]}><i>{x[1]}</i><span><b>{x[2]}</b><small>{x[3]}</small></span><strong>✓</strong></button>)}</div><label className="terms"><input type="checkbox" defaultChecked/> Revisé mi pedido y acepto las condiciones de compra.</label><button className="flow-primary next pay" onClick={()=>setStep("success")}>Pagar {money(final)} →</button><em className="secure">🔒 Transacción cifrada y protegida</em></>}</div><aside><small>RESUMEN DE TU COMPRA</small><h3>{units} {units===1?"producto":"productos"} · {new Set(items.map(x=>x.store)).size} tiendas</h3>{Array.from(new Set(items.map(x=>x.store))).map(store=><div className="summary-store" key={store}><b>◉ {store}</b>{items.filter(x=>x.store===store).map((p,i)=><div key={`${p.id}-${i}`}><i style={{background:p.color}}>{p.image}</i><span><b>{p.name}</b><small>{p.quantity} × {money(p.price)} · {money(p.price*p.quantity)}</small></span></div>)}</div>)}<div className="flow-total"><p><span>Subtotal</span><b>{money(subtotal)}</b></p><p><span>Domicilio</span><b>{fee?money(fee):"Gratis"}</b></p><hr/><p><span>Total</span><strong>{money(final)}</strong></p></div><div className="promise">♡ <span><b>Compra protegida</b><small>Te acompañamos hasta recibir todo.</small></span></div></aside></main></section></>;
}

const dashMenus = [
  ["resumen","▦","Resumen"],["pedidos","□","Pedidos"],["productos","◇","Productos"],["inventario","≋","Inventario"],
  ["clientes","♧","Clientes"],["promociones","%","Promociones"],["reportes","↗","Reportes"],["configuracion","⚙","Configuración"],
];

function Dashboard({customer,profile,organizations,loading,error,onOrganizationsChange}:{customer:{name:string,email:string}|null;profile:UserProfile|null;organizations:OrganizationAccess[];loading:boolean;error:string;onOrganizationsChange:(v:OrganizationAccess[])=>void}){
  const [section,setSection]=useState("resumen");
  const [filter,setFilter]=useState("Todos");
  const [notice,setNotice]=useState("");
  const go=(name:string)=>{setSection(name);setFilter("Todos");window.scrollTo({top:120,behavior:"smooth"})};
  const flash=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2200)};
  return <section className="dashboard">
    {notice&&<div className="dash-toast">✓ {notice}</div>}
    <aside className="dash-side"><div className="dash-store"><span>GM</span><div><b>GoMarket Admin</b><small>{profile?.platform_role==="super_admin"?"Superadministración":"Plan profesional"}</small></div></div>{(profile?.platform_role==="super_admin"?[["proveedores","♙","Proveedores"],...dashMenus]:dashMenus).map(([id,icon,label])=><button onClick={()=>go(id)} className={section===id?"active":""} key={id}><span>{icon}</span> {label}{id==="pedidos"&&<b>8</b>}</button>)}<div className="store-status"><i></i><span><b>Plataforma activa</b><small>Operación protegida</small></span><button>⋮</button></div></aside>
    <div className="dash-main"><IdentityBanner customer={customer} profile={profile} organizations={organizations} loading={loading} error={error}/><DashTop section={section} onAction={flash}/>{section==="proveedores"&&<ProvidersAdmin profile={profile} organizations={organizations} onAction={flash}/>} {section==="resumen"&&<Summary onGo={go}/>} {section==="pedidos"&&<Orders filter={filter} setFilter={setFilter} onAction={flash}/>} {section==="productos"&&<ProductsAdmin filter={filter} setFilter={setFilter} onAction={flash}/>} {section==="inventario"&&<Inventory onAction={flash}/>} {section==="clientes"&&<Customers onAction={flash}/>} {section==="promociones"&&<Promotions onAction={flash}/>} {section==="reportes"&&<Reports/>} {section==="configuracion"&&<Settings onAction={flash} profile={profile} organizations={organizations} onOrganizationsChange={onOrganizationsChange}/>}</div>
  </section>
}

function IdentityBanner({customer,profile,organizations,loading,error}:{customer:{name:string,email:string}|null;profile:UserProfile|null;organizations:OrganizationAccess[];loading:boolean;error:string}){
  if(loading)return <div className="identity-banner loading">Conectando tu panel seguro con GoMarket…</div>;
  if(!customer)return <div className="identity-banner warning"><b>Panel en modo demostración</b><span>Inicia sesión con Google desde el carrito para acceder a datos administrativos.</span></div>;
  if(error)return <div className="identity-banner warning"><b>Sesión iniciada</b><span>{error}</span></div>;
  const role=profile?.platform_role==="super_admin"?"Superadministrador":profile?.platform_role==="platform_admin"?"Administrador de plataforma":"Cliente";
  return <div className="identity-banner"><span className="identity-avatar">{customer.name.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase()}</span><div><b>{customer.name}</b><small>{customer.email}</small></div><i>{role}</i><span className="identity-orgs">{organizations.length?`${organizations.length} empresa${organizations.length===1?"":"s"} vinculada${organizations.length===1?"":"s"}`:"Sin empresa vinculada"}</span></div>
}

function DashTop({section,onAction}:{section:string,onAction:(m:string)=>void}){
  const data:Record<string,[string,string,string]>={proveedores:["SUPERADMINISTRACIÓN","Proveedores","Invita propietarios, supervisa el registro y controla el acceso a GoMarket."],resumen:["Resumen","Buenos días 👋","Tu plataforma está funcionando bien. Aquí tienes el resumen de hoy."],pedidos:["OPERACIÓN","Pedidos","Gestiona, prepara y despacha los pedidos de tu tienda."],productos:["CATÁLOGO","Productos","Administra la información, precios y visibilidad de tus productos."],inventario:["CONTROL DE EXISTENCIAS","Inventario","Supervisa el stock y anticipa faltantes en tiempo real."],clientes:["COMUNIDAD","Clientes","Conoce a tus compradores y fortalece su relación con tu marca."],promociones:["CRECIMIENTO","Promociones","Crea descuentos y campañas para impulsar tus ventas."],reportes:["INTELIGENCIA DE NEGOCIO","Reportes","Convierte tus datos en decisiones claras para crecer."],configuracion:["TU NEGOCIO","Configuración","Gestiona los datos, operación y preferencias de tu tienda."]};
  const d=data[section]; const action=section==="pedidos"?"Exportar pedidos":section==="productos"?"＋ Nuevo producto":section==="promociones"?"＋ Crear promoción":section==="reportes"?"Descargar reporte":"Guardar cambios";
  return <div className="dash-title"><div><span className="kicker">{d[0]}</span><h1>{d[1]}</h1><p>{d[2]}</p></div>{section!=="resumen"&&section!=="inventario"&&section!=="clientes"&&section!=="proveedores"&&<button className="primary" onClick={()=>onAction(section==="configuracion"?"Configuración guardada":"Acción preparada para la conexión con Supabase")}>{action}</button>}</div>
}

function ProvidersAdmin({profile,organizations,onAction}:{profile:UserProfile|null;organizations:OrganizationAccess[];onAction:(m:string)=>void}){
  const [invitations,setInvitations]=useState<ProviderInvitation[]>([]); const [open,setOpen]=useState(false); const [email,setEmail]=useState(""); const [organizationId,setOrganizationId]=useState(organizations[0]?.id||""); const [saving,setSaving]=useState(false); const [error,setError]=useState(""); const [inviteLink,setInviteLink]=useState("");
  const load=async()=>{const {data}=await supabase.from("invitations").select("id,organization_id,email,status,expires_at,created_at,organizations(name)").order("created_at",{ascending:false});setInvitations((data||[]).map((x:any)=>({...x,organizations:Array.isArray(x.organizations)?x.organizations[0]:x.organizations})))};
  useEffect(()=>{if(profile?.platform_role==="super_admin")void load()},[profile]);
  const generateToken=()=>{const bytes=crypto.getRandomValues(new Uint8Array(32));return Array.from(bytes,b=>b.toString(16).padStart(2,"0")).join("")};
  const hashToken=async(token:string)=>Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(token))),b=>b.toString(16).padStart(2,"0")).join("");
  const createInvitation=async()=>{if(!profile||!organizationId||!email.includes("@"))return;setSaving(true);setError("");const rawToken=generateToken();const tokenHash=await hashToken(rawToken);const {data:role,error:roleError}=await supabase.from("roles").select("id").eq("code","owner").is("organization_id",null).single();if(roleError||!role){setSaving(false);setError("No encontramos el rol de propietario.");return}const {error:inviteError}=await supabase.from("invitations").insert({organization_id:organizationId,email:email.trim().toLowerCase(),role_id:role.id,token_hash:tokenHash,invited_by:profile.id,expires_at:new Date(Date.now()+7*86400000).toISOString()});setSaving(false);if(inviteError){setError("No pudimos crear la invitación. Revisa el correo o intenta nuevamente.");return}const publicSite="https://gomarket-colombia.yohanmendozamadera.chatgpt.site";const link=`${publicSite}/?invite=${rawToken}`;setInviteLink(link);await navigator.clipboard?.writeText(link);await load();onAction("Invitación creada y enlace público copiado")};
  const sendMail=()=>{const org=organizations.find(x=>x.id===organizationId)?.name||"tu empresa";const subject=`Invitación para administrar ${org} en GoMarket`;const body=`Hola, te invitamos a completar el registro de ${org} en GoMarket.\n\nAbre este enlace seguro (vence en 7 días):\n${inviteLink}\n\nDebes ingresar con este correo: ${email}`;window.open(`https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(email)}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`,"_blank","noopener,noreferrer")};
  if(profile?.platform_role!=="super_admin")return <div className="admin-card provider-locked"><b>Acceso exclusivo del superadministrador</b><p>Tu cuenta no tiene permiso para administrar proveedores.</p></div>;
  return <><div className="provider-stats"><article><span>Empresas registradas</span><b>{organizations.length}</b><small>Con acceso a la plataforma</small></article><article><span>Invitaciones pendientes</span><b>{invitations.filter(x=>x.status==="pending").length}</b><small>Esperando al propietario</small></article><article><span>Proveedores activos</span><b>{organizations.filter(x=>x.status==="active").length}</b><small>Aprobados en GoMarket</small></article></div><div className="admin-card providers-card"><div className="providers-head"><div><b>Directorio de proveedores</b><small>Empresas, propietarios e invitaciones reales de Supabase</small></div><button className="primary" onClick={()=>{setOpen(true);setInviteLink("")}}>＋ Invitar proveedor</button></div><div className="provider-table"><div className="provider-tr provider-th"><span>Empresa</span><span>Propietario</span><span>Estado</span><span>Acceso</span></div>{organizations.map(org=>{const invite=invitations.find(x=>x.organization_id===org.id);return <div className="provider-tr" key={org.id}><span><i>{org.name.slice(0,2).toUpperCase()}</i><b>{org.name}</b></span><span>{invite?.email||"Por asignar"}</span><span><em className={`provider-status ${org.status}`}>{org.status==="active"?"Activa":org.status}</em></span><span>{invite?<em className={`provider-status ${invite.status}`}>{invite.status==="pending"?"Invitación pendiente":invite.status==="accepted"?"Aceptada":invite.status}</em>:<small>Sin invitación</small>}</span></div>})}</div></div>{open&&<><button className="flow-overlay" onClick={()=>setOpen(false)} aria-label="Cerrar"/><section className="provider-invite-modal"><button className="flow-close" onClick={()=>setOpen(false)}>×</button><span className="kicker">INVITACIÓN SEGURA</span><h2>Invitar propietario proveedor</h2><p>GoMarket prepara el mensaje; tú confirmas el envío desde Gmail.</p><label>Empresa<select value={organizationId} onChange={e=>setOrganizationId(e.target.value)}><option value="">Selecciona una empresa</option>{organizations.map(org=><option value={org.id} key={org.id}>{org.name}</option>)}</select></label><label>Correo del propietario<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="proveedor@empresa.com"/></label>{error&&<small className="form-error">{error}</small>}{inviteLink?<div className="invite-created"><b>✓ Invitación lista para enviar</b><p>Pulsa el botón verde, revisa el mensaje en Gmail y finalmente pulsa <strong>Enviar</strong>.</p><input readOnly value={inviteLink}/><div><button onClick={()=>navigator.clipboard?.writeText(inviteLink)}>Copiar enlace</button><button className="primary" onClick={sendMail}>Abrir Gmail y enviar</button></div></div>:<button className="flow-primary" disabled={saving||!organizationId||!email.includes("@")} onClick={createInvitation}>{saving?"Creando invitación…":"Crear invitación →"}</button>}<small className="invite-note">El enlace vence en 7 días y solo funciona con el correo invitado.</small></section></>}</>
}

function ProviderOnboarding({token,customer}:{token:string;customer:{name:string,email:string}|null}){
  const [invite,setInvite]=useState<{organization_id:string;organization_name:string;invited_email:string;invitation_status:string;expires_at:string}|null>(null); const [loading,setLoading]=useState(true); const [error,setError]=useState(""); const [done,setDone]=useState(false); const [saving,setSaving]=useState(false); const [legalName,setLegalName]=useState(""); const [taxId,setTaxId]=useState(""); const [phone,setPhone]=useState(""); const [address,setAddress]=useState(""); const [city,setCity]=useState("");
  useEffect(()=>{supabase.rpc("get_provider_invitation",{raw_token:token}).then(({data,error})=>{setLoading(false);if(error||!data?.[0])setError("Esta invitación no existe o ya no está disponible.");else{setInvite(data[0]);setLegalName(data[0].organization_name)}})},[token]);
  const login=async()=>{await supabase.auth.signInWithOAuth({provider:"google",options:{redirectTo:window.location.href}})};
  const finish=async()=>{if(!invite||!customer)return;setSaving(true);setError("");const {data:orgId,error:acceptError}=await supabase.rpc("accept_provider_invitation",{raw_token:token});if(acceptError){setSaving(false);setError(acceptError.message.includes("email_mismatch")?`Debes ingresar con ${invite.invited_email}.`:"No pudimos aceptar la invitación. Puede estar vencida.");return}const {error:orgError}=await supabase.from("organizations").update({legal_name:legalName,tax_id:taxId,status:"active"}).eq("id",orgId);const {error:branchError}=await supabase.from("branches").upsert({organization_id:orgId,name:"Sede principal",code:"PRINCIPAL",address,city,phone,is_active:true},{onConflict:"organization_id,code"});setSaving(false);if(orgError||branchError){setError("Tu acceso quedó activado, pero faltó guardar algunos datos. Puedes completarlos desde el panel.");return}setDone(true);window.history.replaceState({},"",window.location.pathname)};
  if(loading)return <main className="onboarding-page"><div className="onboarding-card">Validando invitación segura…</div></main>;
  if(error&&!invite)return <main className="onboarding-page"><div className="onboarding-card error-card"><span>!</span><h1>Invitación no disponible</h1><p>{error}</p><a href="/">Volver a GoMarket</a></div></main>;
  if(done)return <main className="onboarding-page"><div className="onboarding-card done-card"><span>✓</span><h1>¡Tu empresa quedó lista!</h1><p>Ya eres propietario de {invite?.organization_name}. Puedes entrar al panel y continuar configurando productos y pedidos.</p><a href="/">Entrar a GoMarket</a></div></main>;
  return <main className="onboarding-page"><div className="onboarding-brand"><span>go</span><b>market</b></div><section className="onboarding-card"><span className="kicker">ALTA DE PROVEEDOR</span><h1>Completa el registro de {invite?.organization_name}</h1><p>Fuiste invitado como propietario. Estos datos serán revisados y protegidos por GoMarket.</p>{!customer?<div className="onboarding-login"><b>Primero confirma tu identidad</b><small>Debes usar la cuenta {invite?.invited_email}</small><button className="google" onClick={login}><i>G</i> Continuar con Google</button></div>:<><div className="signed-provider"><span>{customer.name.slice(0,1)}</span><div><b>{customer.name}</b><small>{customer.email}</small></div></div>{error&&<small className="form-error">{error}</small>}<div className="onboarding-form"><label>Razón social<input value={legalName} onChange={e=>setLegalName(e.target.value)} placeholder="Nombre legal de la empresa"/></label><label>NIT o documento<input value={taxId} onChange={e=>setTaxId(e.target.value)} placeholder="Ej.: 901.000.000-1"/></label><label>Teléfono<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+57 300 000 0000"/></label><label>Ciudad<input value={city} onChange={e=>setCity(e.target.value)} placeholder="Bogotá"/></label><label className="full">Dirección principal<input value={address} onChange={e=>setAddress(e.target.value)} placeholder="Dirección de la sede"/></label></div><button className="flow-primary" disabled={saving||!legalName||!taxId||!phone||!city||!address} onClick={finish}>{saving?"Guardando información…":"Aceptar invitación y completar registro →"}</button></>}</section></main>
}

function Summary({onGo}:{onGo:(s:string)=>void}){return <><div className="metrics"><article><span>Ventas de hoy <i>↗ 12.4%</i></span><b>$1.284.500</b><small>vs. $1.142.000 ayer</small></article><article onClick={()=>onGo("pedidos")}><span>Pedidos <i>↗ 8.2%</i></span><b>48</b><small>8 pendientes por atender</small></article><article><span>Ticket promedio <i>↗ 3.1%</i></span><b>$26.760</b><small>vs. $25.950 ayer</small></article><article onClick={()=>onGo("inventario")}><span>Productos activos</span><b>126</b><small>4 con stock bajo</small></article></div><div className="dash-grid"><article className="chart-card"><div className="card-title"><div><b>Ventas esta semana</b><small>Ingresos diarios</small></div><button>Últimos 7 días ⌄</button></div><MiniChart/></article><article className="orders-card"><div className="card-title"><div><b>Pedidos recientes</b><small>Actualizados en tiempo real</small></div><button onClick={()=>onGo("pedidos")}>Ver todos →</button></div>{orderData.slice(0,4).map((o)=><OrderMini key={o[0]} o={o}/>)}</article></div></>}
function MiniChart(){return <div className="chart"><div className="ylabels"><span>$1.5M</span><span>$1M</span><span>$500k</span><span>$0</span></div><div className="bars">{[48,65,58,78,72,92,84].map((h,i)=><span key={i}><i style={{height:`${h}%`}}></i><small>{["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"][i]}</small></span>)}</div></div>}
const orderData=[["#GM-2841","Laura Gómez","12:42 p. m.","3 productos","$84.900","Preparando"],["#GM-2840","Carlos Ruiz","12:35 p. m.","2 productos","$42.500","Pendiente"],["#GM-2839","María Díaz","12:18 p. m.","5 productos","$126.800","Despachado"],["#GM-2838","Juan López","11:56 a. m.","1 producto","$36.200","Entregado"],["#GM-2837","Sara Melo","11:31 a. m.","4 productos","$98.400","Aceptado"],["#GM-2836","Diego Torres","11:08 a. m.","2 productos","$54.700","Cancelado"]];
function OrderMini({o}:{o:string[]}){return <div className="order"><span>{o[1].split(" ").map(n=>n[0]).join("")}</span><div><b>{o[1]}</b><small>{o[0]} · {o[2]}</small></div><strong>{o[4]}</strong><i className={o[5].toLowerCase()}>{o[5]}</i></div>}

function Toolbar({placeholder,filters,active,setActive}:{placeholder:string,filters:string[],active?:string,setActive?:(s:string)=>void}){return <div className="admin-toolbar"><label><span>⌕</span><input placeholder={placeholder}/></label><div>{filters.map(x=><button className={active===x?"active":""} onClick={()=>setActive?.(x)} key={x}>{x}</button>)}</div><button className="filter-btn">⚙ Filtros</button></div>}
function Orders({filter,setFilter,onAction}:{filter:string,setFilter:(s:string)=>void,onAction:(m:string)=>void}){const rows=filter==="Todos"?orderData:orderData.filter(o=>o[5]===filter);return <><div className="summary-pills"><span><b>8</b>Pendientes</span><span><b>12</b>Preparando</span><span><b>6</b>Listos</span><span><b>22</b>Completados hoy</span></div><div className="admin-card"><Toolbar placeholder="Buscar por pedido o cliente..." filters={["Todos","Pendiente","Preparando","Despachado","Entregado"]} active={filter} setActive={setFilter}/><div className="data-table order-table"><div className="tr th"><span>Pedido</span><span>Cliente</span><span>Hora</span><span>Contenido</span><span>Total</span><span>Estado</span><span></span></div>{rows.map(o=><button className="tr" key={o[0]} onClick={()=>onAction(`${o[0]} abierto: aquí aparecerá su detalle completo`)}><span><b>{o[0]}</b><small>Entrega a domicilio</small></span><span>{o[1]}</span><span>{o[2]}</span><span>{o[3]}</span><span><b>{o[4]}</b></span><span><i className={`status ${o[5].toLowerCase()}`}>{o[5]}</i></span><span>›</span></button>)}</div><div className="table-foot"><span>Mostrando {rows.length} de 48 pedidos</span><div><button>‹</button><button className="active">1</button><button>2</button><button>3</button><button>›</button></div></div></div></>}

const catalog=[["🥑","Aguacate Hass premium","AGU-001","Frutas","$8.900","42","Activo"],["🍓","Fresas seleccionadas","FRE-014","Frutas","$9.900","8","Stock bajo"],["🥬","Lechuga crespa orgánica","LEC-008","Verduras","$5.400","64","Activo"],["🍅","Tomate chonto premium","TOM-023","Verduras","$6.800","0","Agotado"],["🥔","Papa criolla seleccionada","PAP-011","Tubérculos","$7.200","31","Activo"],["🍋","Limón Tahití","LIM-006","Frutas","$4.500","18","Activo"]];
function ProductsAdmin({filter,setFilter,onAction}:{filter:string,setFilter:(s:string)=>void,onAction:(m:string)=>void}){const rows=filter==="Todos"?catalog:catalog.filter(p=>p[6]===filter);return <div className="admin-card"><Toolbar placeholder="Buscar producto, SKU o categoría..." filters={["Todos","Activo","Stock bajo","Agotado"]} active={filter} setActive={setFilter}/><div className="catalog-tools"><span><b>126 productos</b><small>112 activos · 14 borradores</small></span><button onClick={()=>onAction("Archivo de productos preparado para exportar")}>↓ Exportar</button></div><div className="data-table product-table"><div className="tr th"><span>Producto</span><span>SKU</span><span>Categoría</span><span>Precio</span><span>Stock</span><span>Estado</span><span></span></div>{rows.map(p=><div className="tr" key={p[2]}><span className="product-cell"><i>{p[0]}</i><b>{p[1]}</b></span><span>{p[2]}</span><span>{p[3]}</span><span><b>{p[4]}</b></span><span>{p[5]}</span><span><i className={`status ${p[6].toLowerCase().replace(" ","-")}`}>{p[6]}</i></span><span className="row-actions"><button onClick={()=>onAction(`${p[1]} listo para editar`)}>✎</button><button>⋮</button></span></div>)}</div></div>}

function Inventory({onAction}:{onAction:(m:string)=>void}){return <><div className="metrics inventory-metrics"><article><span>Valor del inventario</span><b>$18.640.000</b><small>Al costo actual</small></article><article><span>Unidades disponibles</span><b>3.842</b><small>En 126 productos</small></article><article><span>Stock bajo</span><b className="warn">4</b><small>Requieren atención</small></article><article><span>Agotados</span><b className="danger">2</b><small>Sin unidades disponibles</small></article></div><div className="dash-grid inventory-grid"><div className="admin-card"><div className="card-title"><div><b>Alertas de inventario</b><small>Productos próximos a agotarse</small></div><button onClick={()=>onAction("Movimiento de inventario listo para registrar")}>＋ Registrar movimiento</button></div>{catalog.filter(p=>+p[5]<20).map(p=><div className="stock-row" key={p[2]}><i>{p[0]}</i><span><b>{p[1]}</b><small>{p[2]} · Mínimo: 10 unidades</small></span><strong className={+p[5]===0?"danger":"warn"}>{p[5]} und.</strong><button onClick={()=>onAction(`Entrada de ${p[1]} preparada`)}>Reponer</button></div>)}</div><div className="admin-card movements"><div className="card-title"><div><b>Movimientos recientes</b><small>Entradas y salidas de hoy</small></div></div>{[["↙","Entrada","Aguacate Hass","+40 und."],["↗","Venta","Fresas seleccionadas","-2 und."],["↗","Ajuste","Tomate chonto","-6 und."],["↙","Devolución","Limón Tahití","+2 und."]].map(x=><div key={x[1]+x[2]}><i className={x[3][0]==="+"?"in":"out"}>{x[0]}</i><span><b>{x[1]}</b><small>{x[2]}</small></span><strong>{x[3]}</strong></div>)}</div></div></>}

function Customers({onAction}:{onAction:(m:string)=>void}){const people=[["LG","Laura Gómez","laura@email.com","18 pedidos","$1.420.600","VIP"],["CR","Carlos Ruiz","carlos@email.com","9 pedidos","$684.200","Frecuente"],["MD","María Díaz","maria@email.com","7 pedidos","$592.100","Frecuente"],["JL","Juan López","juan@email.com","2 pedidos","$96.400","Nuevo"],["SM","Sara Melo","sara@email.com","12 pedidos","$940.800","VIP"]];return <><div className="metrics"><article><span>Clientes totales</span><b>1.284</b><small>+42 este mes</small></article><article><span>Clientes recurrentes</span><b>38%</b><small>+4.6% frente al mes pasado</small></article><article><span>Nuevos este mes</span><b>126</b><small>9 adquiridos hoy</small></article><article><span>Satisfacción</span><b>4.9 ★</b><small>Basado en 382 reseñas</small></article></div><div className="admin-card"><Toolbar placeholder="Buscar por nombre, correo o teléfono..." filters={["Todos","VIP","Frecuentes","Nuevos"]}/><div className="data-table customer-table"><div className="tr th"><span>Cliente</span><span>Contacto</span><span>Compras</span><span>Valor total</span><span>Segmento</span><span></span></div>{people.map(p=><button className="tr" key={p[1]} onClick={()=>onAction(`Perfil de ${p[1]} abierto`)}><span className="customer"><i>{p[0]}</i><b>{p[1]}</b></span><span>{p[2]}</span><span>{p[3]}</span><span><b>{p[4]}</b></span><span><i className="segment">{p[5]}</i></span><span>›</span></button>)}</div></div></>}

function Promotions({onAction}:{onAction:(m:string)=>void}){const promos=[["20%","Frescura de agosto","20% en frutas y verduras","Activa","12 ago","286 usos"],["$8k","Envío que invita","Envío gratis desde $65.000","Programada","15 ago","—"],["2×1","Martes saludable","2×1 en referencias seleccionadas","Borrador","20 ago","—"]];return <><div className="promo-hero"><div><span className="kicker">RECOMENDACIÓN INTELIGENTE</span><h3>Tu categoría de frutas creció 18% esta semana</h3><p>Crea una promoción de fin de semana y aprovecha la tendencia.</p><button onClick={()=>onAction("Borrador de promoción creado")}>Crear campaña sugerida →</button></div><div className="promo-visual"><span>18%</span><small>crecimiento</small></div></div><div className="promo-grid">{promos.map(p=><article key={p[1]}><div><span>{p[0]}</span><i className={`status ${p[3].toLowerCase()}`}>{p[3]}</i></div><h3>{p[1]}</h3><p>{p[2]}</p><footer><span><small>Finaliza</small><b>{p[4]}</b></span><span><small>Redenciones</small><b>{p[5]}</b></span><button onClick={()=>onAction(`${p[1]} lista para editar`)}>⋮</button></footer></article>)}</div></>}

function Reports(){return <><div className="report-filter"><div><button className="active">7 días</button><button>30 días</button><button>Este año</button></div><label>01 ago 2026 — 07 ago 2026</label></div><div className="metrics"><article><span>Ventas netas <i>↗ 14.2%</i></span><b>$8.462.300</b><small>+$1.054.000 vs. periodo anterior</small></article><article><span>Utilidad estimada <i>↗ 11.8%</i></span><b>$2.961.800</b><small>Margen del 35%</small></article><article><span>Pedidos <i>↗ 8.6%</i></span><b>326</b><small>Ticket promedio $25.958</small></article><article><span>Clientes nuevos <i>↗ 21.3%</i></span><b>74</b><small>Conversión del 4.8%</small></article></div><div className="dash-grid"><article className="chart-card report-chart"><div className="card-title"><div><b>Rendimiento de ventas</b><small>Ventas vs. utilidad</small></div><span className="legend">● Ventas　● Utilidad</span></div><MiniChart/></article><article className="admin-card top-products"><div className="card-title"><div><b>Productos más vendidos</b><small>Por ingresos generados</small></div></div>{catalog.slice(0,5).map((p,i)=><div key={p[2]}><b>{i+1}</b><i>{p[0]}</i><span><strong>{p[1]}</strong><small>{42-i*6} unidades vendidas</small></span><em>{money(374000-i*43800)}</em></div>)}</article></div></>}

function Settings({onAction,profile,organizations,onOrganizationsChange}:{onAction:(m:string)=>void;profile:UserProfile|null;organizations:OrganizationAccess[];onOrganizationsChange:(v:OrganizationAccess[])=>void}){
  const [tab,setTab]=useState("Información"); const [companyName,setCompanyName]=useState(""); const [saving,setSaving]=useState(false); const [formError,setFormError]=useState("");
  const createCompany=async()=>{if(!profile||!companyName.trim())return;setSaving(true);setFormError("");const slug=`${companyName.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")}-${Date.now().toString().slice(-5)}`;const {data,error}=await supabase.from("organizations").insert({name:companyName.trim(),slug,owner_user_id:profile.id,status:"active",approved_by:profile.id,approved_at:new Date().toISOString()}).select("id,name,slug,status").single();setSaving(false);if(error){setFormError("No fue posible crear la empresa. Intenta nuevamente.");return}onOrganizationsChange([...organizations,{...data,memberRole:"Propietario"}]);setCompanyName("");onAction("Empresa creada y vinculada correctamente")};
  return <div className="settings-layout"><nav>{["Información","Horarios","Domicilios","Pagos","Equipo","Notificaciones"].map(x=><button className={tab===x?"active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</nav><div className="admin-card settings-card"><div className="card-title"><div><b>{tab} de la tienda</b><small>Configura cómo funciona y se presenta tu negocio.</small></div></div>{tab==="Información"?<div className="settings-form"><label className="logo-upload"><span>GM</span><button onClick={()=>onAction("Selector de imagen preparado")}>Cambiar logo</button><small>PNG o JPG · Máximo 2 MB</small></label>{organizations.length?<div className="real-org-list">{organizations.map(org=><div key={org.id}><span><b>{org.name}</b><small>{org.memberRole} · {org.status==="active"?"Activa":org.status}</small></span><i>Conectada a Supabase</i></div>)}</div>:<div className="create-company"><b>Crea tu primera empresa</b><p>Este registro será real y quedará protegido dentro de Supabase.</p><label>Nombre comercial<input value={companyName} onChange={e=>setCompanyName(e.target.value)} placeholder="Ej.: Huerta del Valle"/></label>{formError&&<small className="form-error">{formError}</small>}<button className="primary" disabled={!profile||!companyName.trim()||saving} onClick={createCompany}>{saving?"Creando…":"Crear empresa"}</button></div>}</div>:tab==="Equipo"?<TeamAccess profile={profile} organizations={organizations} onAction={onAction}/>:<div className="setting-placeholder"><span>{tab==="Horarios"?"◷":tab==="Domicilios"?"⌖":tab==="Pagos"?"▣":"♢"}</span><h3>Configuración de {tab.toLowerCase()}</h3><p>Esta sección está preparada para conectarse a las reglas reales del negocio.</p><button className="primary" onClick={()=>onAction(`Configuración de ${tab.toLowerCase()} actualizada`)}>Configurar {tab.toLowerCase()}</button></div>}</div></div>
}

function TeamAccess({profile,organizations,onAction}:{profile:UserProfile|null;organizations:OrganizationAccess[];onAction:(m:string)=>void}){
  const role=profile?.platform_role==="super_admin"?"Superadministrador":"Usuario";
  return <div className="team-access"><div className="access-summary"><span>Tu acceso</span><b>{role}</b><small>{role==="Superadministrador"?"Control total de la plataforma, empresas, roles y auditoría.":"Tus permisos dependen de la empresa a la que perteneces."}</small></div><div className="team-list"><header><div><b>Empresas y permisos</b><small>Información consultada desde Supabase</small></div><button onClick={()=>onAction(organizations.length?"La invitación segura estará disponible en el siguiente paso":"Primero crea una empresa")}>＋ Invitar empleado</button></header>{organizations.length?organizations.map(org=><div className="team-row" key={org.id}><span>{org.name.slice(0,2).toUpperCase()}</span><div><b>{org.name}</b><small>{org.memberRole}</small></div><i>{org.status==="active"?"Activo":org.status}</i><button onClick={()=>onAction(`Permisos de ${org.name} preparados para administrar`)}>Administrar</button></div>):<div className="team-empty">Crea una empresa en la pestaña Información para comenzar a invitar empleados y asignar permisos.</div>}</div></div>
}
